import type { PurchaseOrderRow, ShipmentRow } from '@/lib/vendor-supabase/types'; type DashboardKpis = { pendingPos: number; activeDeliveries: number; pendingInvoices: number; openTickets: number;
}; type ModalKind = 'quotation' | 'shipment' | 'invoice' | 'compliance' | 'viewShipment' | null; type QuotationForm = { rfq_id: string; total_amount: string; notes: string;
}; type ShipmentForm = { po_id: string; carrier_name: string; tracking_number: string; driver_contact: string;
}; type ComplianceForm = { document_type: string; registration_number: string; expiry_date: string; file_url: string;
}; const emptyQuotation: QuotationForm = { rfq_id: '', total_amount: '', notes: '' };
